import simpson = require( './index' );


// TESTS //

// The function returns a number...
{
	simpson( (x: number): number => x*x, 0, 1, 100 ); // $ExpectType number
}

// The compiler throws an error if arguments are invalid...
{
	simpson( true as any, 0, 1, 100 ); // $ExpectError
	simpson( (x: number): number => x, '0' as any, 1, 100 ); // $ExpectError
	simpson( (x: number): number => x, 0, '1' as any, 100 ); // $ExpectError
	simpson( (x: number): number => x, 0, 1, '100' as any ); // $ExpectError
}

// The compiler throws an error if insufficient arguments...
{
	simpson(); // $ExpectError
	simpson( (x: number): number => x ); // $ExpectError
}
